<?php require_once __DIR__.'/includes/functions.php'; require_login(); $id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT); if(!$id){http_response_code(400);exit('Invalid certificate reference.');} $sql="SELECT r.id,r.administered_on,r.notes,c.full_name,c.date_of_birth,c.parent_id,v.name vaccine_name,v.dose,h.name hospital_name,h.address,h.city FROM vaccination_records r JOIN children c ON c.id=r.child_id JOIN vaccines v ON v.id=r.vaccine_id JOIN hospitals h ON h.id=r.hospital_id WHERE r.id=?"; $stmt=db()->prepare($sql);$stmt->execute([$id]);$r=$stmt->fetch(); if(!$r){http_response_code(404);exit('Certificate not found.');} if(current_user()['role']==='parent'){ if((int)$r['parent_id']!==(int)current_user()['id']){http_response_code(403);exit('You cannot access this certificate.');} } elseif(!in_array(current_user()['role'],['admin','hospital'],true)){http_response_code(403);exit('Access denied.');} $serial='ND-'.date('Y').'-'.str_pad((string)$r['id'],6,'0',STR_PAD_LEFT); ?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Vaccination Certificate · <?=e($serial)?></title><link rel="stylesheet" href="<?=BASE_URL?>/assets/style.css"><style>body{background:#f4f1fa;color:#25233a}.certificate-wrap{max-width:980px;margin:36px auto;padding:22px}.certificate{position:relative;background:#fff;padding:clamp(28px,6vw,76px);border:1px solid #e6def5;outline:8px solid #fff;box-shadow:0 25px 80px #31215b18;overflow:hidden}.certificate:before,.certificate:after{content:"";position:absolute;width:220px;height:220px;border:1px solid #d9c9f4;border-radius:50%;right:-90px;top:-90px}.certificate:after{width:160px;height:160px;right:-60px;top:-60px}.cert-top{display:flex;justify-content:space-between;gap:20px;align-items:center;border-bottom:1px solid #eee8f8;padding-bottom:24px}.cert-brand{font-weight:800;color:#6554bd;font-size:22px}.cert-kicker{font-size:11px;letter-spacing:.2em;color:#77718e;text-transform:uppercase}.cert-title{text-align:center;padding:48px 0 26px}.cert-title h1{font-family:Georgia,serif;font-size:clamp(32px,6vw,54px);font-weight:500;color:#3b315c;margin:10px 0}.cert-name{font-family:Georgia,serif;font-size:clamp(26px,4vw,40px);color:#6554bd;text-align:center;border-bottom:1px solid #ddd2f0;padding:12px 10px 22px;margin:0 auto 28px;max-width:650px}.cert-copy{text-align:center;line-height:1.9;color:#69647a;max-width:650px;margin:0 auto}.cert-details{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px;margin:34px 0}.cert-detail{background:#f8f6fc;padding:16px;border-radius:12px}.cert-detail small{display:block;color:#858097;font-size:10px;letter-spacing:.12em;text-transform:uppercase;margin-bottom:6px}.cert-detail strong{font-size:15px;color:#302b48}.cert-bottom{display:flex;justify-content:space-between;align-items:end;gap:20px;border-top:1px solid #eee8f8;padding-top:24px;color:#77718e;font-size:12px}.seal{width:76px;height:76px;border:2px solid #c8b9ea;border-radius:50%;display:grid;place-items:center;text-align:center;color:#6554bd;font-size:10px;font-weight:800;flex-shrink:0}.cert-actions{display:flex;justify-content:center;gap:12px;margin:24px}@media(max-width:600px){.certificate-wrap{padding:10px;margin:12px auto}.cert-top,.cert-bottom{align-items:flex-start;flex-direction:column}.cert-details{grid-template-columns:1fr}.cert-title{padding:30px 0 18px}}@media print{body{background:#fff}.certificate-wrap{margin:0;padding:0;max-width:none}.certificate{box-shadow:none;outline:0;border:8px double #d8c9f1;min-height:250mm}.cert-actions{display:none}@page{size:A4;margin:12mm}}</style></head><body><div class="certificate-wrap"><article class="certificate"><div class="cert-top"><div class="cert-brand">✚ NurtureDose</div><div class="cert-kicker">Official vaccination record</div></div><div class="cert-title"><div class="cert-kicker">Certificate of immunisation</div><h1>Vaccination Certificate</h1><p class="muted">This record recognises the vaccination entry recorded below.</p></div><div class="cert-name"><?=e($r['full_name'])?></div><p class="cert-copy">This is to certify that the above-named child has a vaccination record entered in the NurtureDose system by the listed care provider. Keep this document with the child's health records.</p><div class="cert-details"><div class="cert-detail"><small>Vaccine</small><strong><?=e($r['vaccine_name'])?></strong></div><div class="cert-detail"><small>Dose</small><strong><?=e($r['dose'])?></strong></div><div class="cert-detail"><small>Date administered</small><strong><?=e(date('d F Y',strtotime($r['administered_on'])))?></strong></div><div class="cert-detail"><small>Certificate reference</small><strong><?=e($serial)?></strong></div><div class="cert-detail"><small>Hospital / care provider</small><strong><?=e($r['hospital_name'])?></strong></div><div class="cert-detail"><small>Provider location</small><strong><?=e(trim($r['address'].', '.$r['city'],', '))?></strong></div></div><div class="cert-bottom"><div><strong>Issued by NurtureDose</strong><br>Generated from a recorded vaccination entry.<br>For clinical verification, contact the listed provider.</div><div class="seal">RECORD<br>VERIFIED<br>ENTRY</div></div></article><div class="cert-actions"><button class="button primary" onclick="window.print()">Print / Save as PDF ↗</button><a class="button secondary" href="<?=BASE_URL?>/parent/index.php">Back to dashboard</a></div></div></body></html>